/* Z80 interpreter for SMSEmu (Sega Master System on the Tamagotchi Paradise). Author: mameise.
 * Header only: the includer defines the memory and port access first:
 *   Z_RD(a)      read a byte (a is 16 bit)
 *   Z_WR(a, v)   write a byte
 *   Z_IN(p)      read a port (p: 16 bit, low byte is the port)
 *   Z_OUT(p, v)  write a port
 * Flags kept in F as on the chip (S Z Y H X P/V N C), tables for sign, zero and parity.
 * The opcode cases are generated by gen_z80.py into z80_ops.inc. */
#ifndef SMS_Z80_H
#define SMS_Z80_H
#include <stdint.h>

typedef union { uint16_t w; struct { uint8_t l, h; } b; } ZPair;
typedef struct {
  ZPair af, bc, de, hl, ix, iy, sp, wz;
  uint16_t pc, af2, bc2, de2, hl2;
  uint8_t i, r, r7, im, iff1, iff2, halt, ei;
  uint8_t irq;        /* the INT line (held by the VDP) */
  uint8_t nmi;        /* NMI pending (pause key) */
  int32_t cyc;        /* cycles still to run */
} Z80;

#define CF 0x01
#define NF 0x02
#define PF 0x04
#define VF 0x04
#define XF 0x08
#define HF 0x10
#define YF 0x20
#define ZF 0x40
#define SF 0x80

static uint8_t zSZ[256], zSZP[256], zSZBIT[256], zINC[256], zDEC[256];
static void z80_tables(void)
{
  for (int i = 0; i < 256; i++) {
    int p = 0; for (int k = 0; k < 8; k++) p ^= (i >> k) & 1;
    zSZ[i] = (uint8_t)((i ? i & SF : ZF) | (i & (YF | XF)));
    zSZBIT[i] = (uint8_t)((i ? i & SF : ZF | PF) | (i & (YF | XF)));
    zSZP[i] = (uint8_t)(zSZ[i] | (p ? 0 : PF));
    zINC[i] = (uint8_t)(zSZ[i] | (i == 0x80 ? VF : 0) | ((i & 0x0F) == 0 ? HF : 0));
    zDEC[i] = (uint8_t)(zSZ[i] | NF | (i == 0x7F ? VF : 0) | ((i & 0x0F) == 0x0F ? HF : 0));
  }
}

#define A  z->af.b.h
#define F  z->af.b.l
#define B  z->bc.b.h
#define C  z->bc.b.l
#define D  z->de.b.h
#define E  z->de.b.l
#define H  z->hl.b.h
#define L  z->hl.b.l
#define AF z->af.w
#define BC z->bc.w
#define DE z->de.w
#define HL z->hl.w
#define SP z->sp.w
#define WZ z->wz.w
#define PC z->pc
#define RD(a) Z_RD((uint16_t)(a))
#define WR(a, v) Z_WR((uint16_t)(a), (uint8_t)(v))
#define IMM8() RD(PC++)
#define RD16(a) ((uint16_t)(RD(a) | RD((uint16_t)((a) + 1)) << 8))
#define WR16(a, v) do { uint16_t a_ = (uint16_t)(a), v_ = (uint16_t)(v); WR(a_, v_ & 0xFF); WR((uint16_t)(a_ + 1), v_ >> 8); } while (0)

static inline uint16_t z_imm16(Z80 *z) { uint16_t lo = IMM8(); uint16_t hi = IMM8(); return (uint16_t)(lo | hi << 8); }
static inline void z_push(Z80 *z, uint16_t v) { SP -= 2; WR16(SP, v); }
static inline uint16_t z_pop(Z80 *z) { uint16_t v = RD16(SP); SP += 2; return v; }

static inline void z_add(Z80 *z, uint8_t v) { unsigned a = A, r = a + v; F = (uint8_t)(zSZ[r & 0xFF] | ((r >> 8) & CF) | ((a ^ r ^ v) & HF) | (((v ^ a ^ 0x80) & (v ^ r) & 0x80) >> 5)); A = (uint8_t)r; }
static inline void z_adc(Z80 *z, uint8_t v) { unsigned a = A, r = a + v + (F & CF); F = (uint8_t)(zSZ[r & 0xFF] | ((r >> 8) & CF) | ((a ^ r ^ v) & HF) | (((v ^ a ^ 0x80) & (v ^ r) & 0x80) >> 5)); A = (uint8_t)r; }
static inline void z_sub(Z80 *z, uint8_t v) { unsigned a = A, r = a - v; F = (uint8_t)(zSZ[r & 0xFF] | ((r >> 8) & CF) | NF | ((a ^ r ^ v) & HF) | (((v ^ a) & (a ^ r) & 0x80) >> 5)); A = (uint8_t)r; }
static inline void z_sbc(Z80 *z, uint8_t v) { unsigned a = A, r = a - v - (F & CF); F = (uint8_t)(zSZ[r & 0xFF] | ((r >> 8) & CF) | NF | ((a ^ r ^ v) & HF) | (((v ^ a) & (a ^ r) & 0x80) >> 5)); A = (uint8_t)r; }
static inline void z_cp(Z80 *z, uint8_t v) { unsigned a = A, r = a - v; F = (uint8_t)((zSZ[r & 0xFF] & (SF | ZF)) | (v & (YF | XF)) | ((r >> 8) & CF) | NF | ((a ^ r ^ v) & HF) | (((v ^ a) & (a ^ r) & 0x80) >> 5)); }
static inline void z_and(Z80 *z, uint8_t v) { A &= v; F = (uint8_t)(zSZP[A] | HF); }
static inline void z_or(Z80 *z, uint8_t v) { A |= v; F = zSZP[A]; }
static inline void z_xor(Z80 *z, uint8_t v) { A ^= v; F = zSZP[A]; }
static inline uint8_t z_inc(Z80 *z, uint8_t v) { v++; F = (uint8_t)((F & CF) | zINC[v]); return v; }
static inline uint8_t z_dec(Z80 *z, uint8_t v) { v--; F = (uint8_t)((F & CF) | zDEC[v]); return v; }
static inline uint16_t z_add16(Z80 *z, uint16_t a, uint16_t b)
{
  uint32_t r = (uint32_t)a + b; WZ = (uint16_t)(a + 1);
  F = (uint8_t)((F & (SF | ZF | VF)) | (((a ^ r ^ b) >> 8) & HF) | ((r >> 16) & CF) | ((r >> 8) & (YF | XF)));
  return (uint16_t)r;
}
static inline void z_adc16(Z80 *z, uint16_t b)
{
  uint32_t a = HL, r = a + b + (F & CF); WZ = (uint16_t)(a + 1);
  F = (uint8_t)((((a ^ r ^ b) >> 8) & HF) | ((r >> 16) & CF) | ((r >> 8) & (SF | YF | XF)) | ((r & 0xFFFF) ? 0 : ZF) | (((b ^ a ^ 0x8000) & (b ^ r) & 0x8000) >> 13));
  HL = (uint16_t)r;
}
static inline void z_sbc16(Z80 *z, uint16_t b)
{
  uint32_t a = HL, r = a - b - (F & CF); WZ = (uint16_t)(a + 1);
  F = (uint8_t)((((a ^ r ^ b) >> 8) & HF) | NF | ((r >> 16) & CF) | ((r >> 8) & (SF | YF | XF)) | ((r & 0xFFFF) ? 0 : ZF) | (((b ^ a) & (a ^ r) & 0x8000) >> 13));
  HL = (uint16_t)r;
}
static inline uint8_t z_rlc(Z80 *z, uint8_t v) { uint8_t r = (uint8_t)(v << 1 | v >> 7); F = (uint8_t)(zSZP[r] | (v >> 7)); return r; }
static inline uint8_t z_rrc(Z80 *z, uint8_t v) { uint8_t r = (uint8_t)(v >> 1 | v << 7); F = (uint8_t)(zSZP[r] | (v & 1)); return r; }
static inline uint8_t z_rl(Z80 *z, uint8_t v) { uint8_t r = (uint8_t)(v << 1 | (F & CF)); F = (uint8_t)(zSZP[r] | (v >> 7)); return r; }
static inline uint8_t z_rr(Z80 *z, uint8_t v) { uint8_t r = (uint8_t)(v >> 1 | (F & CF) << 7); F = (uint8_t)(zSZP[r] | (v & 1)); return r; }
static inline uint8_t z_sla(Z80 *z, uint8_t v) { uint8_t r = (uint8_t)(v << 1); F = (uint8_t)(zSZP[r] | (v >> 7)); return r; }
static inline uint8_t z_sra(Z80 *z, uint8_t v) { uint8_t r = (uint8_t)(v >> 1 | (v & 0x80)); F = (uint8_t)(zSZP[r] | (v & 1)); return r; }
static inline uint8_t z_sll(Z80 *z, uint8_t v) { uint8_t r = (uint8_t)(v << 1 | 1); F = (uint8_t)(zSZP[r] | (v >> 7)); return r; }
static inline uint8_t z_srl(Z80 *z, uint8_t v) { uint8_t r = (uint8_t)(v >> 1); F = (uint8_t)(zSZP[r] | (v & 1)); return r; }
static inline void z_bit(Z80 *z, int b, uint8_t v) { F = (uint8_t)((F & CF) | HF | (zSZBIT[v & (1u << b)] & ~(YF | XF)) | (v & (YF | XF))); }
static inline void z_bitm(Z80 *z, int b, uint8_t v, uint8_t hi) { F = (uint8_t)((F & CF) | HF | (zSZBIT[v & (1u << b)] & ~(YF | XF)) | (hi & (YF | XF))); }
static inline uint8_t z_rot(Z80 *z, int k, uint8_t v)
{
  switch (k) { case 0: return z_rlc(z, v); case 1: return z_rrc(z, v); case 2: return z_rl(z, v); case 3: return z_rr(z, v);
    case 4: return z_sla(z, v); case 5: return z_sra(z, v); case 6: return z_sll(z, v); default: return z_srl(z, v); }
}
static inline void z_daa(Z80 *z)
{
  uint8_t a = A;
  if (F & NF) { if ((F & HF) || (A & 0x0F) > 9) a -= 6; if ((F & CF) || A > 0x99) a -= 0x60; }
  else { if ((F & HF) || (A & 0x0F) > 9) a += 6; if ((F & CF) || A > 0x99) a += 0x60; }
  F = (uint8_t)((F & (CF | NF)) | (A > 0x99 ? CF : 0) | ((A ^ a) & HF) | zSZP[a]);
  A = a;
}
static inline void z_ldi(Z80 *z, int d)
{
  uint8_t v = RD(HL); WR(DE, v); HL += d; DE += d; BC--;
  uint8_t n = (uint8_t)(v + A);
  F = (uint8_t)((F & (SF | ZF | CF)) | (n & XF) | ((n << 4) & YF) | (BC ? VF : 0));
}
static inline void z_cpi(Z80 *z, int d)
{
  uint8_t v = RD(HL), r = (uint8_t)(A - v); HL += d; BC--; WZ += d;
  F = (uint8_t)((F & CF) | (zSZ[r] & ~(YF | XF)) | ((A ^ v ^ r) & HF) | NF);
  if (F & HF) r--;
  F |= (uint8_t)((r & XF) | ((r << 4) & YF) | (BC ? VF : 0));
}
static inline void z_ini(Z80 *z, int d)
{
  uint8_t t = Z_IN(BC); WZ = (uint16_t)(BC + d); B--; WR(HL, t); HL += d;
  unsigned t2 = t + (uint8_t)(C + d);
  F = (uint8_t)(zSZ[B] | ((t & SF) ? NF : 0) | ((t2 & 0x100) ? HF | CF : 0) | (zSZP[(uint8_t)((t2 & 7) ^ B)] & PF));
}
static inline void z_outi(Z80 *z, int d)
{
  uint8_t t = RD(HL); B--; WZ = (uint16_t)(BC + d); Z_OUT(BC, t); HL += d;
  unsigned t2 = t + L;
  F = (uint8_t)(zSZ[B] | ((t & SF) ? NF : 0) | ((t2 & 0x100) ? HF | CF : 0) | (zSZP[(uint8_t)((t2 & 7) ^ B)] & PF));
}

static void z80_reset(Z80 *z)
{
  uint8_t *p = (uint8_t *)z; for (unsigned i = 0; i < sizeof *z; i++) p[i] = 0;
  AF = 0xFFFF; SP = 0xFFFF; z->ix.w = z->iy.w = 0xFFFF;
}

/* DD and FD: the ones that use HL, H, L or (HL) take IX / IY. Returns the cycles, or 0: run the opcode plainly
 * (4 cycles more). */
static int z80_xy(Z80 *z, uint16_t *xy, uint8_t op);
static int z80_ed(Z80 *z, uint8_t op);
static int z80_cb(Z80 *z, uint8_t op);

static inline uint8_t z_fetch(Z80 *z) { z->r++; return IMM8(); }

/* run until the cycles are used up (z->cyc += n first) */
static void z80_run(Z80 *z, int32_t n)
{
  z->cyc += n;
  while (z->cyc > 0) {
    if (z->ei) z->ei = 0;
    else if (z->nmi) {
      z->nmi = 0; z->halt = 0; z->iff1 = 0; z->r++;
      z_push(z, PC); PC = 0x66; WZ = PC; z->cyc -= 11;
    } else if (z->irq && z->iff1) {
      z->halt = 0; z->iff1 = z->iff2 = 0; z->r++;
      z_push(z, PC);
      if (z->im == 2) { PC = RD16((uint16_t)(z->i << 8 | 0xFF)); z->cyc -= 19; }
      else { PC = 0x38; z->cyc -= 13; }
      WZ = PC;
    }
    if (z->halt) { int32_t k = (z->cyc + 3) >> 2; z->r = (uint8_t)(z->r + k); z->cyc -= k << 2; break; }
    uint8_t op = z_fetch(z);
    int t;
  again:
    switch (op) {
#include "z80_ops.inc"
    }
    z->cyc -= t;
  }
}
#include "z80_fns.inc"
#undef A
#undef F
#undef B
#undef C
#undef D
#undef E
#undef H
#undef L
#undef AF
#undef BC
#undef DE
#undef HL
#undef SP
#undef WZ
#undef PC
#undef RD
#undef WR
#undef IMM8
#undef RD16
#undef WR16

#endif
